/* ==================== USART2 UI Designer Command Interface ==================== */
#define UART2_LINE_MAX     128U
#define UART2_LINE_QUEUE   16U
#define UART2_LINE_MASK    (UART2_LINE_QUEUE - 1U)
uint8_t uart2_rx_byte;
static char uart2_rx_build[UART2_LINE_MAX];
static uint8_t uart2_rx_idx = 0;
static char uart2_line_queue[UART2_LINE_QUEUE][UART2_LINE_MAX];
static volatile uint8_t uart2_q_head = 0;
static volatile uint8_t uart2_q_tail = 0;

/* Layout overrides from designer */
static int16_t layout_x[32];
static int16_t layout_y[32];
static uint8_t layout_dirty = 0;

void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart) {
  if (huart->Instance == USART2) {
    uint8_t ch = uart2_rx_byte;
    if (ch == '\n' || ch == '\r') {
      if (uart2_rx_idx > 0) {
        uint8_t next = (uint8_t)((uart2_q_tail + 1U) & UART2_LINE_MASK);
        if (next != uart2_q_head) {
          uart2_rx_build[uart2_rx_idx] = 0;
          memcpy(uart2_line_queue[uart2_q_tail], uart2_rx_build, uart2_rx_idx + 1U);
          uart2_q_tail = next;
        }
        uart2_rx_idx = 0;
      }
    } else {
      if (ch >= 0x20U && ch <= 0x7EU) {
        if (uart2_rx_idx < UART2_LINE_MAX - 1U) {
          uart2_rx_build[uart2_rx_idx++] = (char)ch;
        } else {
          uart2_rx_idx = 0;
        }
      } else {
        uart2_rx_idx = 0;
      }
    }
    HAL_UART_Receive_IT(&huart2, &uart2_rx_byte, 1);
  }
}

void USART2_IRQHandler(void) {
  HAL_UART_IRQHandler(&huart2);
}

static void ui_draw_pc_icon(uint8_t connected) {
  lcd_fill_rect(8, 58, 24, 75, UI_BG);
  if (!connected) return;
  lcd_fill_rect(8, 58, 24, 72, UI_DARK);
  lcd_fill_rect(8, 58, 24, 59, UI_GREY);
  lcd_fill_rect(8, 71, 24, 72, UI_GREY);
  lcd_fill_rect(8, 58, 9, 72, UI_GREY);
  lcd_fill_rect(23, 58, 24, 72, UI_GREY);
  lcd_fill_rect(12, 73, 20, 75, UI_GREY);
}

static void ui_draw_mode_center(const char *mode, uint16_t color) {
  int n = (int)strlen(mode);
  int x = 60 - (n * 12) / 2;
  if (x < 34) x = 34;
  ui_draw_16((uint16_t)x, 66, mode, color);
}

static void spectrum_passband_x(int out_n, int *x0, int *x1) {
  int64_t f0, f1;
  int64_t center = (int64_t)ui_active_freq();
  if (strcmp(ui.rx_demod, "USB") == 0) {
    f0 = center; f1 = center + 3000;
  } else if (strcmp(ui.rx_demod, "LSB") == 0) {
    f0 = center - 3000; f1 = center;
  } else if (strcmp(ui.rx_demod, "AM") == 0) {
    f0 = center - 4500; f1 = center + 4500;
  } else if (strcmp(ui.rx_demod, "FM") == 0) {
    f0 = center - 12500; f1 = center + 12500;
  } else if (strcmp(ui.rx_demod, "CW") == 0) {
    f0 = center - 600; f1 = center + 600;
  } else {
    f0 = center - 1000; f1 = center + 1000;
  }
  *x0 = (int)((f0 * out_n) / (int64_t)SP_FMAX_HZ);
  *x1 = (int)((f1 * out_n) / (int64_t)SP_FMAX_HZ);
  if (*x0 < 0) *x0 = 0;
  if (*x1 >= out_n) *x1 = out_n - 1;
}

static uint8_t uart2_pop_line(char *out, uint16_t cap) {
  uint8_t ok = 0;
  __disable_irq();
  if (uart2_q_head != uart2_q_tail) {
    uint16_t i = 0;
    while (i + 1U < cap && uart2_line_queue[uart2_q_head][i]) {
      out[i] = uart2_line_queue[uart2_q_head][i];
      i++;
    }
    out[i] = 0;
    uart2_q_head = (uint8_t)((uart2_q_head + 1U) & UART2_LINE_MASK);
    ok = 1;
  }
  __enable_irq();
  return ok;
}

void ui_designer_process(void) {
  char buf[UART2_LINE_MAX];
  while (uart2_pop_line(buf, sizeof buf)) {
  ui.pc_connected = 1;
  g_pc_last_tick = HAL_GetTick();
  /* Reply */
  char reply[192];   /* STAT 回包 + 频率/键控状态 */
  int n;

  if (strncmp(buf, "HELLO", 5) == 0) {
    n = snprintf(reply, sizeof reply, "OK HELLO\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  } else if (strncmp(buf, "PING", 4) == 0) {
    n = snprintf(reply, sizeof reply, "PONG\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  } else if (strncmp(buf, "REDRAW", 6) == 0) {
    ui_draw_static();
    n = snprintf(reply, sizeof reply, "OK\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  } else if (strncmp(buf, "POS,", 4) == 0) {
    /* POS,id,x,y - just acknowledge for now */
    n = snprintf(reply, sizeof reply, "OK\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  } else if (strncmp(buf, "FILL,", 5) == 0) {
    /* v63-上位机: 全屏填充测试色 FILL,r,g,b (0-255) - 验证上位机->主机->屏幕链路。
     * 频谱/瀑布区会被主循环频谱绘制覆盖, 其余区域保持填充色; CLR 恢复界面。 */
    int r = 0, g = 0, b = 0;
    if (sscanf(buf + 5, "%d,%d,%d", &r, &g, &b) >= 1) {
      if (r < 0) r = 0; if (r > 255) r = 255;
      if (g < 0) g = 0; if (g > 255) g = 255;
      if (b < 0) b = 0; if (b > 255) b = 255;
      lcd_fill_rect(0, 0, 479, 319, ILI9488_RGB565((uint8_t)r, (uint8_t)g, (uint8_t)b));
      n = snprintf(reply, sizeof reply, "OK FILL %d,%d,%d\n", r, g, b);
    } else n = snprintf(reply, sizeof reply, "ERR FILL\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  } else if (strncmp(buf, "TXT,", 4) == 0) {
    /* v63-上位机: 屏幕显示文字 TXT,x,y,scale,text (scale 1-3, ASCII) */
    int x = 0, y = 0, sc = 1;
    char txt[64]; txt[0] = 0;
    if (sscanf(buf + 4, "%d,%d,%d,%63[^\n\r]", &x, &y, &sc, txt) >= 3) {
      if (sc < 1) sc = 1; if (sc > 3) sc = 3;
      if (x < 0) x = 0; if (x > 460) x = 460;
      if (y < 0) y = 0; if (y > 300) y = 300;
      ui_draw_text((uint16_t)x, (uint16_t)y, txt, ILI9488_RGB565(255,255,255), (uint8_t)sc);
      n = snprintf(reply, sizeof reply, "OK TXT\n");
    } else n = snprintf(reply, sizeof reply, "ERR TXT\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  } else if (strncmp(buf, "CLR", 3) == 0) {
    /* v63-上位机: 恢复频谱界面(重绘静态 UI, 频谱循环自动恢复) */
    ui_draw_static();
    n = snprintf(reply, sizeof reply, "OK\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }

  /* ============ 上位机控制命令(屏幕状态 + SPI 透传从机) ============ */
  else if (strncmp(buf, "RX ", 3) == 0) {
    int v = 0; sscanf(buf + 3, "%d", &v);
    ui.rx_mode = v ? 1 : 0;
    if (ui.rx_mode) ui.tx_key = 0;
    spi_cmd_post(buf);   /* v67: 转发从机 RX 模式切换 */
    si5351_set_lo(ui_active_freq());
    ui_update_dynamic(0);
    n = snprintf(reply, sizeof reply, "OK RX %d\n", ui.rx_mode);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "TX ", 3) == 0) {
    int v = 0; sscanf(buf + 3, "%d", &v);
    ui.tx_key = v ? 1 : 0;
    ui.rx_mode = ui.tx_key ? 0 : 1;
    spi_cmd_priority_post(buf);   /* PTT/key path is latency-critical */
    ui_update_dynamic(0);
    n = snprintf(reply, sizeof reply, "OK TX %d\n", ui.tx_key);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "PTT ", 4) == 0) {
    int v = 0; sscanf(buf + 4, "%d", &v);
    ui.tx_key = v ? 1 : 0;
    ui.rx_mode = ui.tx_key ? 0 : 1;
    spi_cmd_priority_post(buf);   /* v70: never block PTT behind a frame */
    ui_update_dynamic(0);
    n = snprintf(reply, sizeof reply, "OK PTT %d\n", v ? 1 : 0);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "FDX ", 4) == 0) {
    int v = 0; sscanf(buf + 4, "%d", &v);
    ui.full_duplex = v ? 1 : 0;
    spi_cmd_post(buf);   /* v69: keep RX ADC/demod/PCM alive in TX view */
    n = snprintf(reply, sizeof reply, "OK FDX %d\n", ui.full_duplex);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "MODE ", 5) == 0) {
    int m = 0; sscanf(buf + 5, "%d", &m);
    if (m == 8)      strcpy(ui.tx_mode, "AM");
    else if (m == 7) strcpy(ui.tx_mode, "FM");
    else if (m == 6) strcpy(ui.tx_mode, "CW");
    else if (m == 1) strcpy(ui.tx_mode, "CAR");
    else if (m == 0) strcpy(ui.tx_mode, ui.side ? "USB" : "LSB");
    spi_cmd_priority_post(buf);   /* mode change is latency-critical */
    ui_update_dynamic(0);
    n = snprintf(reply, sizeof reply, "OK MODE %d\n", m);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "SIDE ", 5) == 0) {
    int v = 0; sscanf(buf + 5, "%d", &v);
    ui.side = v ? 1 : 0;
    if (strcmp(ui.tx_mode, "USB") == 0 || strcmp(ui.tx_mode, "LSB") == 0)
      strcpy(ui.tx_mode, ui.side ? "USB" : "LSB");
    spi_cmd_priority_post(buf);   /* sideband change is latency-critical */
    ui_update_dynamic(0);
    n = snprintf(reply, sizeof reply, "OK SIDE %d\n", ui.side);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "VFO ", 4) == 0) {
    char v = 0;
    unsigned long f = 0;
    if (sscanf(buf + 4, " %c %lu", &v, &f) == 2) {
      if (f > 50000000UL) f = 50000000UL;
      if (v == 'A' || v == 'a') {
        ui.vfo_a_hz = (uint32_t)f;
        ui.vfo_active = 0;
      } else if (v == 'B' || v == 'b') {
        ui.vfo_b_hz = (uint32_t)f;
        ui.vfo_active = 1;
      } else {
        n = snprintf(reply, sizeof reply, "ERR VFO\n");
        HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
        return;
      }
      si5351_set_lo(ui_active_freq());
      ui_update_dynamic(0);
      n = snprintf(reply, sizeof reply, "OK VFO %c %lu\n",
                   ui.vfo_active ? 'B' : 'A', (unsigned long)ui_active_freq());
    } else {
      n = snprintf(reply, sizeof reply, "ERR VFO\n");
    }
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "DEMOD ", 6) == 0) {
    int f = 0, mi = 0;
    if (sscanf(buf + 6, "%d %d", &f, &mi) >= 1) {
      if (f < 0) f = 0; if (f > 50000000) f = 50000000;
      ui_set_active_freq((uint32_t)f);
      /* 上位机解调模式索引: 0=AM 1=FM 2=USB 3=LSB 4=CW */
      if (mi == 0)      strcpy(ui.rx_demod, "AM");
      else if (mi == 1) strcpy(ui.rx_demod, "FM");
      else if (mi == 2) strcpy(ui.rx_demod, "USB");
      else if (mi == 3) strcpy(ui.rx_demod, "LSB");
      else if (mi == 4) strcpy(ui.rx_demod, "CW");
      spi_cmd_priority_post(buf);   /* RX mode/frequency is latency-critical */
      si5351_set_lo(ui_active_freq());
      ui_update_dynamic(0);
      n = snprintf(reply, sizeof reply, "OK DEMOD %d %d\n", f, mi);
    } else n = snprintf(reply, sizeof reply, "ERR DEMOD\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "FREQ ", 5) == 0) {
    int f = 0;
    if (sscanf(buf + 5, "%d", &f) == 1) {
      if (f < 0) f = 0;
      if (f > 50000000) f = 50000000;
      ui_set_active_freq((uint32_t)f);
      spi_cmd_priority_post(buf);   /* frequency change is latency-critical */
      si5351_set_lo(ui_active_freq());
      ui_update_dynamic(0);
      n = snprintf(reply, sizeof reply, "OK FREQ %d\n", f);
    } else n = snprintf(reply, sizeof reply, "ERR FREQ\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "TUNE ", 5) == 0) {
    /* v71: single-command retune.  The PC debounces the tuning control and
     * sends only the settled frequency, so the slave gets exactly one NCO
     * update per step instead of a VFO+FREQ+DEMOD burst that used to
     * overflow the in-band command slot. */
    int f = 0;
    if (sscanf(buf + 5, "%d", &f) == 1) {
      if (f < 0) f = 0;
      if (f > 50000000) f = 50000000;
      ui_set_active_freq((uint32_t)f);
      spi_cmd_priority_post(buf);   /* relay TUNE <f> to the slave as-is */
      si5351_set_lo(ui_active_freq());
      ui_update_dynamic(0);
      n = snprintf(reply, sizeof reply, "OK TUNE %d\n", f);
    } else n = snprintf(reply, sizeof reply, "ERR TUNE\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "SPMIN ", 6) == 0) {
    int v = -100; sscanf(buf + 6, "%d", &v);
    if (v < -140) v = -140;
    if (v > (int)g_sp_db_ceil - 10) v = (int)g_sp_db_ceil - 10;
    g_sp_db_floor = (float)v;
    n = snprintf(reply, sizeof reply, "OK SPMIN %d\n", v);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "SPMAX ", 6) == 0) {
    int v = -20; sscanf(buf + 6, "%d", &v);
    if (v > 20) v = 20;
    if (v < (int)g_sp_db_floor + 10) v = (int)g_sp_db_floor + 10;
    g_sp_db_ceil = (float)v;
    n = snprintf(reply, sizeof reply, "OK SPMAX %d\n", v);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "DGAIN ", 6) == 0) {
    int v = 0; sscanf(buf + 6, "%d", &v);
    ui.dgain = (int16_t)v;
    spi_cmd_post(buf);   /* v67: 转发从机音频增益 */
    n = snprintf(reply, sizeof reply, "OK DGAIN %d\n", (int)ui.dgain);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "HPF ", 4) == 0) {
    int v = 0; sscanf(buf + 4, "%d", &v);
    ui.hpf = v ? 1 : 0;
    spi_cmd_post(buf);   /* v67: 转发从机 50Hz 高通 */
    n = snprintf(reply, sizeof reply, "OK HPF %d\n", (int)ui.hpf);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "NR ", 3) == 0) {
    int en = 0, level = 1;
    sscanf(buf + 3, "%d %d", &en, &level);
    ui.nr_en = en ? 1 : 0;
    if (level < 1) level = 1;
    if (level > 3) level = 3;
    ui.nr_level = (uint8_t)level;
    spi_cmd_post(buf);
    n = snprintf(reply, sizeof reply, "OK NR %d %d\n", ui.nr_en, ui.nr_level);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else if (strncmp(buf, "STAT", 4) == 0) {
    int m = (strcmp(ui.tx_mode, "AM") == 0) ? 8
          : (strcmp(ui.tx_mode, "FM") == 0) ? 7
          : (strcmp(ui.tx_mode, "CW") == 0) ? 6
          : (strcmp(ui.tx_mode, "CAR") == 0) ? 1 : 0;
    int rm = (strcmp(ui.rx_demod, "AM") == 0) ? 0
           : (strcmp(ui.rx_demod, "FM") == 0) ? 1
           : (strcmp(ui.rx_demod, "USB") == 0) ? 2
           : (strcmp(ui.rx_demod, "LSB") == 0) ? 3 : 4;
    n = snprintf(reply, sizeof reply,
        "STAT MODE=%d RXMODE=%d SIDE=%d FREQ=%lu SPMIN=%d SPMAX=%d RX=%d FDX=%d HEALTH=%02X TXKEY=%d DGAIN=%d HPF=%d NR=%d NRL=%d IGAIN=%d QGAIN=%d PHASE=%d QUAD=%d IDC=%d QDC=%d AGAIN=%d\n",
        m, rm, ui.side, (unsigned long)ui_active_freq(),
        (int)g_sp_db_floor, (int)g_sp_db_ceil, ui.rx_mode,
        (int)ui.full_duplex, (unsigned)g_health_flags,
        (int)ui.tx_key, (int)ui.dgain, (int)ui.hpf, (int)ui.nr_en, (int)ui.nr_level,
        cfg_igain, cfg_qgain, cfg_phase,
        cfg_quad, cfg_idc, cfg_qdc, cfg_again);
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
  else {
    /* 校准参数 IGAIN/QGAIN/PHASE/QUAD/IDC/QDC/AGAIN <val> */
    char pn[8]; int pv = 0;
    if (sscanf(buf, "%7s %d", pn, &pv) == 2) {
      spi_cmd_post(buf);   /* v67: 转发从机校准参数 */
      if      (strcmp(pn, "IGAIN") == 0) cfg_igain = pv;
      else if (strcmp(pn, "QGAIN") == 0) cfg_qgain = pv;
      else if (strcmp(pn, "PHASE") == 0) cfg_phase = pv;
      else if (strcmp(pn, "QUAD")  == 0) cfg_quad  = pv;
      else if (strcmp(pn, "IDC")   == 0) cfg_idc   = pv;
      else if (strcmp(pn, "QDC")   == 0) cfg_qdc   = pv;
      else if (strcmp(pn, "AGAIN") == 0) cfg_again = pv;
      else { n = snprintf(reply, sizeof reply, "ERR\n"); HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100); return; }
      n = snprintf(reply, sizeof reply, "OK %s %d\n", pn, pv);
    } else n = snprintf(reply, sizeof reply, "ERR\n");
    HAL_UART_Transmit(&huart2, (uint8_t*)reply, n, 100);
  }
}
}
